-- SQLite 3 / PostgreSQL common SQL; synthetic data only
CREATE TABLE orders(order_id TEXT PRIMARY KEY, order_amount INTEGER);
CREATE TABLE lines(order_id TEXT, line_amount INTEGER);
INSERT INTO orders VALUES ('U',90),('V',40);
INSERT INTO lines VALUES ('U',10),('U',20);

-- 1. Raw join: U 90 10; U 90 20; V 40 NULL
SELECT o.*,l.line_amount FROM orders o
LEFT JOIN lines l ON l.order_id=o.order_id ORDER BY o.order_id;
-- Raw row count=3; distinct order count=2; sum(order_amount)=220

-- 2. Restore order grain before joining
WITH per_order AS (
 SELECT order_id,SUM(line_amount) AS line_total
 FROM lines GROUP BY order_id
)
SELECT o.*,p.line_total FROM orders o
LEFT JOIN per_order p ON p.order_id=o.order_id ORDER BY o.order_id;
-- U 90 30; V 40 NULL; order total=130

-- 3. Matching filter: V is retained
SELECT o.order_id,l.line_amount FROM orders o
LEFT JOIN lines l ON l.order_id=o.order_id AND l.line_amount>15;
-- U 20; V NULL

-- 4. Post-join filter: V is removed (NULL > 15 is not true)
SELECT o.order_id,l.line_amount FROM orders o
LEFT JOIN lines l ON l.order_id=o.order_id WHERE l.line_amount>15;
-- U 20
