def accepted(age):
    return type(age) is int and 18 <= age <= 60

cases = [(17,False),(18,True),(19,True),(30,True),
         (59,True),(60,True),(61,False),(None,False),(18.5,False)]
for age,expected in cases:
    assert accepted(age) == expected

# Mutant has an exclusive upper bound. Case 60 must kill it.
def mutant(age):
    return type(age) is int and 18 <= age < 60
assert mutant(60) != accepted(60)

