import unittest
def total(values):
    return sum(values)
class TotalTests(unittest.TestCase):
    def test_normal(self):
        self.assertEqual(total([2, 3]), 5)
    def test_empty(self):
        self.assertEqual(total([]), 0)
if __name__ == '__main__':
    unittest.main()
